// src/components/GraphCanvas.jsx
import { useEffect, useRef } from "react";

// Deterministic seeded pseudo-random (same as Python stub in embedder.py)
function seededRand(seed) {
  const x = Math.sin(Math.abs(seed) + 1) * 10000;
  return x - Math.floor(x);
}

function strHash(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
  return Math.abs(h);
}

// Compute edges from evidence list using same logic as EvidenceGraphBuilder:
//   - same source → always connect (weight ≥ 0.5)
//   - different source → connect if seeded similarity > threshold
// allNodes = full candidate list (including pruned-out); prunedEvidence = selected ones
function computeEdges(allNodes, edgeThreshold) {
  const edges = [];
  for (let i = 0; i < allNodes.length; i++) {
    for (let j = i + 1; j < allNodes.length; j++) {
      const ni = allNodes[i], nj = allNodes[j];
      let weight;
      if (ni.source === nj.source) {
        // Same source → structural edge, always included
        const sim = seededRand(strHash(ni.source) % 9999);
        weight = Math.max(0.5, sim * 0.5 + 0.5);
      } else {
        // Use seeded sim based on both contents
        const seed = strHash((ni.content || "") + (nj.content || "")) % 77777;
        const sim = seededRand(seed);
        const thr = ni.modality !== nj.modality ? edgeThreshold * 0.9 : edgeThreshold;
        weight = sim > thr ? sim : 0;
      }
      if (weight > 0) {
        edges.push({ src: i, dst: j, weight });
      }
    }
  }
  return edges;
}

export default function GraphCanvas({
  allNodes = [],       // full list of all candidates (selected + pruned-out)
  prunedEvidence = [], // only the GCP-selected nodes
  edgeThreshold = 0.4,
  serverEdges = [],    // real edges from backend (preferred when non-empty)
}) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    // Use allNodes if available, fall back to prunedEvidence for backward-compat
    const nodes = allNodes.length > 0 ? allNodes : prunedEvidence;
    if (!canvas || nodes.length === 0) return;

    const parent = canvas.parentElement;
    const W = parent.offsetWidth || 400;
    const H = parent.offsetHeight || 280;
    canvas.width = W;
    canvas.height = H;
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, W, H);

    const n = nodes.length;
    const cx = W / 2;
    const cy = (H - 30) / 2 + 8; // leave room for legend at bottom
    const r = Math.min(W * 0.42, (H - 60) * 0.42);

    const positions = nodes.map((_, i) => ({
      x: cx + r * Math.cos((2 * Math.PI * i / n) - Math.PI / 2),
      y: cy + r * Math.sin((2 * Math.PI * i / n) - Math.PI / 2),
    }));

    // Build selected id set from prunedEvidence
    const selectedIds = new Set(prunedEvidence.map(e => e.id));
    // Also build a map from node id → index in `nodes` array
    const idToIdx = {};
    nodes.forEach((nd, i) => { idToIdx[nd.id] = i; });

    // ── Compute edges ────────────────────────────────────────────────
    // Prefer real edges from the server; compute client-side as fallback
    const edges = serverEdges.length > 0 ? serverEdges : computeEdges(nodes, edgeThreshold);

    // ── Draw edges first (behind nodes) ─────────────────────────────
    for (const edge of edges) {
      const s = positions[edge.src];
      const d = positions[edge.dst];
      if (!s || !d) continue;

      const srcSelected = selectedIds.has(nodes[edge.src]?.id);
      const dstSelected = selectedIds.has(nodes[edge.dst]?.id);
      const bothSelected = srcSelected && dstSelected;
      const eitherSelected = srcSelected || dstSelected;

      ctx.beginPath();
      ctx.moveTo(s.x, s.y);
      ctx.lineTo(d.x, d.y);

      if (bothSelected) {
        // Bright cyan edge between two selected nodes
        ctx.strokeStyle = `rgba(0,229,255,${0.15 + edge.weight * 0.45})`;
        ctx.lineWidth = 1 + edge.weight * 1.5;
      } else if (eitherSelected) {
        // Dimmer edge when only one end is selected
        ctx.strokeStyle = `rgba(0,229,255,${0.06 + edge.weight * 0.1})`;
        ctx.lineWidth = 0.8;
      } else {
        // Both pruned out — very faint
        ctx.strokeStyle = "rgba(30,42,56,0.7)";
        ctx.lineWidth = 0.6;
      }
      ctx.stroke();
    }

    // ── Draw nodes ───────────────────────────────────────────────────
    nodes.forEach((doc, i) => {
      const pos = positions[i];
      const selected = selectedIds.has(doc.id);
      const nodeR = selected ? 8 : 4;

      // Glow halo for selected
      if (selected) {
        const grd = ctx.createRadialGradient(pos.x, pos.y, 0, pos.x, pos.y, 20);
        grd.addColorStop(0, "rgba(0,229,255,0.2)");
        grd.addColorStop(1, "rgba(0,229,255,0)");
        ctx.fillStyle = grd;
        ctx.beginPath();
        ctx.arc(pos.x, pos.y, 20, 0, Math.PI * 2);
        ctx.fill();
      }

      // Node circle
      ctx.beginPath();
      ctx.arc(pos.x, pos.y, nodeR, 0, Math.PI * 2);
      ctx.fillStyle = selected ? "#00e5ff" : "#1a2535";
      ctx.strokeStyle = selected ? "#00e5ff" : "#2e3f52";
      ctx.lineWidth = 1.2;
      ctx.fill();
      ctx.stroke();

      // Importance arc ring (green arc showing importance score)
      if (selected) {
        const imp = doc.importance_score != null ? Math.min(doc.importance_score, 1) : 0.5;
        ctx.beginPath();
        ctx.arc(pos.x, pos.y, nodeR + 3.5,
          -Math.PI / 2,
          -Math.PI / 2 + imp * Math.PI * 2);
        ctx.strokeStyle = "rgba(16,185,129,0.75)";
        ctx.lineWidth = 1.8;
        ctx.stroke();
      }

      // Source label above node
      ctx.fillStyle = selected ? "#c8daea" : "#3a4a5c";
      ctx.font = `bold 8px "Space Mono", monospace`;
      ctx.textAlign = "center";
      const label = (doc.source || `node_${i}`).split("_")[0].toUpperCase().slice(0, 5);
      ctx.fillText(label, pos.x, pos.y - (nodeR + 6));
    });

    // ── Legend ───────────────────────────────────────────────────────
    const ly = H - 16;
    // Selected
    ctx.fillStyle = "rgba(0,229,255,0.85)";
    ctx.beginPath(); ctx.arc(14, ly, 5, 0, Math.PI * 2); ctx.fill();
    // Green arc on legend dot
    ctx.beginPath();
    ctx.arc(14, ly, 8, -Math.PI / 2, Math.PI / 2);
    ctx.strokeStyle = "rgba(16,185,129,0.7)";
    ctx.lineWidth = 1.5; ctx.stroke();
    ctx.fillStyle = "#6b7c93"; ctx.font = '8px "Space Mono"'; ctx.textAlign = "left";
    ctx.fillText("Selected", 24, ly + 3);

    // Pruned out
    ctx.fillStyle = "#1a2535"; ctx.strokeStyle = "#2e3f52"; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(98, ly, 4, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.fillStyle = "#6b7c93";
    ctx.fillText("Pruned out", 108, ly + 3);

    // Edge legend
    ctx.beginPath();
    ctx.moveTo(185, ly); ctx.lineTo(208, ly);
    ctx.strokeStyle = "rgba(0,229,255,0.45)"; ctx.lineWidth = 1.5; ctx.stroke();
    ctx.fillStyle = "#6b7c93";
    ctx.fillText("Edge", 213, ly + 3);

  }, [allNodes, prunedEvidence, edgeThreshold, serverEdges]);

  return <canvas ref={canvasRef} style={{ width: "100%", height: "100%", display: "block" }} />;
}
